#!/usr/bin/env python3
from gaussian_parser import Checkpoint
import sys

# decode keys from gaussian_parser here
# note, that parsed key can also be split by get_Energy which will give last float in line
gausskeys = {'total_energy': '_Total_Energy', 
        'gradient': '_Cartesian_Gradient', 
        'dipole_moment': '_Dipole_Moment', 
        'scf_energy': 'SCF_Energy', 
        'natoms': '_Number_of_atoms', 
        'atoms': '_Int_Atom_Types', 
        'MM_charges': '_MM_charges',
        'atom_numbers': '_Atomic_numbers', 
        'nonadiabatic_coupling': '_Nonadiabatic_coupling', 
        'charge': '_Charge', 
        'real_atomic_weights': '_Real_atomic_weights', 
        'coord': '_Current_cartesian_coordinates', 
        'g_version': '_Gaussian_Version', 
        'nuc_charges': '_Nuclear_charges',
        'mulliken_charges': '_Mulliken_Charges'}

keys = gausskeys.keys()

def translate_gaussian(fchk, getlist):
    data = {}
    cp = Checkpoint(fchk).parseCheckpointFile()
    for i in getlist:
        try:
            data[i] = cp[gausskeys[i]]
        except:
            data[i] = get_Energy(fchk, i)
    return data

def get_Energy(filen, search):
    with open(filen) as f:
        a = f.readlines()
        for i in a:
            if search in i:
                return(float(i.split(' ')[-1]))

